contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address token, address[] memory tos, uint[] memory v, uint amount) public payable {
        require(tos.length > 0);
        require(v.length == tos.length);
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;

        bool reverted;
        bool ret = false;
        try c.transfer{value: amount}(from, token, tos, v) returns (bool r) {
